Lemma disjoint_from_app2 : forall (X Y : list (Z * Z)) a n, disjoint_from X a n -> disjoint_from Y a n -> disjoint_from (X ++ Y) a n.
Proof. induction X as [|[l h] X IH]; intros Y a n DX DY; cbn in *; [exact DY| split; [tauto| apply IH; tauto]]. Qed.

Lemma accessible_transport_scr : forall LF m0 X XS m m' O n,
  as_RFS H LF m0 -> fsobj H LF O n -> aapp O n -> 0 <= n ->
  accessible m O n -> munch (X ++ XS) m m' -> Forall awin X -> Forall (fs_scratch H LF) XS -> accessible m' O n.
Proof.
  intros LF m0 X XS m m' O n RF FO AP Hn AC MU FX FS.
  pose proof (aapp_bounds _ _ AP Hn) as (B1 & B2 & B3 & B4 & B5).
  eapply accessible_transport; [exact AC| exact MU|]. intros x Hx. apply outside_app. split.
  - apply awin_outside_sh; [exact FX| lia].
  - pose proof (disjoint_scratch_sh H HH LF m0 XS x 1 RF ltac:(eapply fsobj_sub; [exact FO| lia| lia]) ltac:(lia) ltac:(lia)
                  ltac:(eapply aapp_sub; [exact AP| lia| lia]) FS) as D.
    eapply disjoint_outside; [exact D|]. unfold nsh. change ((1 + 7) / 8) with 1. lia.
Qed.

Lemma addressable_transport_scr : forall LF m0 X XS m m' O n,
  as_RFS H LF m0 -> fsobj H LF O n -> aapp O n ->
  addressable m O n -> munch (X ++ XS) m m' -> wmono asegs m m' -> Forall awin X -> Forall (fs_scratch H LF) XS -> addressable m' O n.
Proof.
  intros LF m0 X XS m m' O n RF FO AP AD MU WM FX FS. pose proof AD as (Hn & _).
  pose proof (aapp_bounds _ _ AP Hn) as (B1 & B2 & B3 & B4 & B5).
  eapply addressable_transport; [exact AD| exact MU| exact WM|]. apply disjoint_from_app2.
  - apply awin_disjoint_shland; [exact FX| apply sh_ge_lowsh; lia| apply sh_nsh_high; lia].
  - eapply (disjoint_scratch_sh H HH); [exact RF| exact FO| exact Hn| lia| exact AP| exact FS].
Qed.

Lemma RHEAP_transport_scr : forall s LB LF m0 X XS m m',
  as_RHEAP H s LB m -> as_RFS H LF m0 -> munch (X ++ XS) m m' -> wmono asegs m m' ->
  Forall (aclient_write_ok H LB) X -> Forall (fs_scratch H LF) XS -> as_RHEAP H s LB m'.
Proof.
  intros s LB LF m0 X XS m m' RH RF MU WM FX FS.
  eapply (ah_RHEAP_frame H HH); [exact RH| exact MU| exact WM|]. apply Forall_app. split; [exact FX|].
  exact (proj1 (scratch_Forall H HH LF m0 LB XS RF FS)).
Qed.


