Lemma sub_fp_scr : forall lo sp v hv (XS : list (Z * Z)) l h d dh (XS1 : list (Z * Z)),
  lo <= l -> h <= sp -> v <= d -> dh <= hv -> (forall x, outside XS x -> outside XS1 x) ->
  sub_fp ((l, h) :: (d, dh) :: XS1)%Z ((lo, sp) :: (v, hv) :: XS)%Z.
Proof.
  intros lo sp v hv XS l h d dh XS1 H1 H2 H3 H4 HS x O. cbn in O |- *. destruct O as (O1 & O2 & O3).
  split; [lia| split; [lia| apply HS; exact O3]].
Qed.
