Lemma rw_cells_transport_scr_hi : forall LF m0 X XS m m' A cs,
  as_RFS H LF m0 -> aceil <= A ->
  rw_cells asegs m A cs -> munch (X ++ XS) m m' -> wmono asegs m m' -> disjoint_from X A (Z.of_nat (cells_size cs)) ->
  Forall (fs_scratch H LF) XS -> rw_cells asegs m' A cs.
Proof.
  intros LF m0 X XS m m' A cs RF HA RC MU WM DX FS.
  eapply rw_cells_transport; [exact RC| exact MU| exact WM|]. apply disjoint_from_app2; [exact DX|].
  exact (proj2 (proj2 (scratch_Forall H HH LF m0 [] XS RF FS)) A _ HA).
Qed.

Lemma stk_transport_scr : forall LF m0 X XS m m' l h,
  as_RFS H LF m0 -> aceil <= l ->
  stk asegs m l h -> munch (X ++ XS) m m' -> wmono asegs m m' -> disjoint_from X l (h - l) ->
  Forall (fs_scratch H LF) XS -> stk asegs m' l h.
Proof.
  intros LF m0 X XS m m' l h RF HA ST MU WM DX FS.
  eapply stk_transport_disjoint; [exact ST| exact MU| exact WM|]. apply disjoint_from_app2; [exact DX|].
  exact (proj2 (proj2 (scratch_Forall H HH LF m0 [] XS RF FS)) l _ HA).
Qed.

Lemma bytes_at_transport_scr : forall LF m0 X XS m m' A bs,
  as_RFS H LF m0 -> (bs <> [] -> fsobj H LF A (Z.of_nat (length bs)) /\ aapp A (Z.of_nat (length bs))) ->
  bytes_at asegs m A bs -> munch (X ++ XS) m m' -> disjoint_from X A (Z.of_nat (length bs)) ->
  Forall (fs_scratch H LF) XS -> bytes_at asegs m' A bs.
Proof.
  intros LF m0 X XS m m' A bs RF OB BA MU DX FS.
  destruct bs as [|b0 bs']; [eapply bytes_at_nil; exact BA|].
  destruct (OB ltac:(congruence)) as [FO AP].
  pose proof (aapp_bounds _ _ AP ltac:(lia)) as (B1 & B2 & B3 & B4 & B5).
  eapply bytes_at_transport; [exact BA| exact MU|]. apply disjoint_from_app2; [exact DX|].
  eapply (disjoint_scratch H HH); [exact RF| exact FO| lia| lia| exact AP| exact FS].
Qed.

