Definition scrW (ff fp : Z) : list (Z * Z) := [(as_FSB H, as_FSB H + AFS_FLAGS); (fp, fp + 1); (ff, ff + 64); (sh ff, sh ff + 8)]%Z.

Lemma scrW_scratch : forall LF ff fp, fresh_frame H LF 0 ff fp -> Forall (fs_scratch H LF) (scrW ff fp).
Proof. intros LF ff fp FF. exact (fs_scratch_of_fresh H LF 0 ff fp FF). Qed.

Lemma svc_W_split : forall lo sp dst n ff fp, svc_W H lo sp dst n ff fp = [(lo, bv_unsigned sp); (dst, dst + n)]%Z ++ scrW ff fp.
Proof. reflexivity. Qed.

(* [comment removed for export] *)
Definition win_obj (LB : list block) (LF : list fframe) (m : mem) (bs : list byte) (A : Z) : Prop :=
  bs <> [] -> aobj LB LF A (zlength bs) /\ accessible m A (zlength bs).

Lemma win_obj_awin : forall LB LF W m m' bs A, win_obj LB LF m bs A -> munch W m m' -> Forall awin W -> win_obj LB LF m' bs A.
Proof. intros LB LF W m m' bs A WO MU FW NE. destruct (WO NE) as [AO AC]. split; [exact AO| eapply accessible_transport_awin; eauto]. Qed.

Lemma win_obj_scr : forall s LB LF m0 m1 X XS m m' bs A,
  as_RHEAP H s LB m0 -> as_RFS H LF m1 -> win_obj LB LF m bs A -> munch (X ++ XS) m m' -> Forall awin X -> Forall (fs_scratch H LF) XS ->
  win_obj LB LF m' bs A.
Proof.
  intros s LB LF m0 m1 X XS m m' bs A RH RF WO MU FX FS NE. destruct (WO NE) as [AO AC]. split; [exact AO|].
  eapply (accessible_transport_scr LF m1 X XS m m'); [exact RF| eapply (aobj_fsobj H HH); [exact RH| exact AO]
    | eapply (aobj_aapp H HH); [exact RH| exact RF| exact AO] | unfold zlength; lia| exact AC| exact MU| exact FX| exact FS].
Qed.


Lemma win_obj_fs : forall s LB LF m0 m1 m bs A, as_RHEAP H s LB m0 -> as_RFS H LF m1 -> win_obj LB LF m bs A ->
  bs <> [] -> fsobj H LF A (Z.of_nat (length bs)) /\ aapp A (Z.of_nat (length bs)).
Proof.
  intros s LB LF m0 m1 m bs A RH RF WO NE. destruct (WO NE) as [AO _]. unfold zlength in AO.
  split; [eapply (aobj_fsobj H HH); [exact RH| exact AO]| eapply (aobj_aapp H HH); [exact RH| exact RF| exact AO]].
Qed.

(* [comment removed for export] *)
Lemma win_svc_obj : forall s LB LF m bs A, as_RHEAP H s LB m -> as_RFS H LF m -> win_obj LB LF m bs A -> svc_obj H LF m bs A.
Proof.
  intros s LB LF m bs A RH RF WO NE. destruct (WO NE) as [AO AC]. unfold X8_svcopy.zlength. unfold zlength in *.
  split; [eapply (aobj_aapp H HH); [exact RH| exact RF| exact AO]|]. split; [exact AC|].
  split; [eapply (aobj_shvis H HH); [exact RH| exact RF| exact AO| lia]| eapply (aobj_fsobj H HH); [exact RH| exact AO]].
Qed.

