Definition P_A_TCNE_RET1 : Z := 0xbaacc.     (* [comment removed for export] *)

Definition tc_scan_post (sp' : word) gp tp (t2 : word) (nl np f : Z) (s3 : word) (s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 : word)
    (F : bvmap 5 word) (fc : bv 32) (vp : Z) (name value : list byte) (m1 : mem) : machine_state -> Prop :=
  fun ms' => exists t0 t1 a1 a2 a3 a4 a5 a6 a7 vp',
    ms' = MS (mkR (Z_to_bv 64 P_A_TCNE_RET1) sp' gp tp t0 t1 t2 (Z_to_bv 64 nl) (Z_to_bv 64 np)
                  (Z_to_bv 64 (elem_block_size name (trim value))) a1 a2 a3 a4 a5 a6 a7
                  (Z_to_bv 64 f) s3 (Z_to_bv 64 (zlength (trim value))) (Z_to_bv 64 vp') s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F (Z_to_bv 64 AOPNEW) fc None m1 (seg_rom asegs)
    /\ bytes_at asegs m1 vp' (trim value)
    /\ ((vp <= vp' /\ vp' + zlength (trim value) <= vp + zlength value) \/ (vp' = 0 /\ trim value = [])).

Lemma ebs_eq : forall name tv,
  elem_block_size name tv = (zlength name + zlength tv + 67) - (zlength name + zlength tv + 67) mod 8.
