Section Scan.
  Variables (rax sp' : word) (gp tp t2 : word) (nl np f : Z) (s3 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 : word) (F : bvmap 5 word) (fc : bv 32).
  Variables (vp : Z) (name value : list byte) (m1 : mem).
  Hypothesis VB : bytes_at asegs m1 vp value.
  Hypothesis NL : 0 <= nl <= 65533.
  Hypothesis NLE : zlength name = nl.
  Hypothesis VL : zlength value <= 65533.
  Hypothesis MI : mem_inv asegs m1.
Scheme kc__5 := Elimination for Corelib.Init.Logic.or Sort Prop.
Scheme kc__6 := Elimination for Corelib.Init.Datatypes.list Sort Prop.

  Lemma tc_join : forall (X0 X1 X2 vp' : Z) (t0 t1 a3 a4 a5 a6 a7 s4x s5x : word),
    bytes_at asegs m1 vp' (trim value) ->
    0 <= X0 < 2^64 -> 0 <= X1 < 2^64 -> 0 <= X2 < 2^64 ->
    ( (X2 = X1 /\ trim value = [] /\ vp' = 0)
