    (f np vp ec : Z) (name value : list byte) (lo : Z) (m : mem) : machine_state -> Prop :=
  fun ms' => exists t0 t1 t2 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 m' junk vp',
    ms' = MS (mkR (Z_to_bv 64 P_A_TCNE_RET1) (Z_to_bv 64 (bv_unsigned sp + -80)) gp tp t0 t1 t2
                  (Z_to_bv 64 (zlength name)) (Z_to_bv 64 np) (Z_to_bv 64 (elem_block_size name (trim value))) a1 a2 a3 a4 a5 a6 a7
                  (Z_to_bv 64 f) (Z_to_bv 64 ec) (Z_to_bv 64 (zlength (trim value))) (Z_to_bv 64 vp') s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F (Z_to_bv 64 AOPNEW) fc None m' (seg_rom asegs)
    /\ munch [(lo, bv_unsigned sp)]%Z m m' /\ wmono asegs m m' /\ mem_inv asegs m'
