Definition TC_SEG2_STACK : Z := 80 + VT_STACK.

(* [comment removed for export] *)
Definition tc_seg2_post (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (s : as_St H) (LB : list block) (LF : list fframe)
    (A f np vp' : Z) (name tv : list byte) (junkB : list byte) (lo shi : Z) (m : mem) : machine_state -> Prop :=
  fun ms' => exists t0 t1 t2 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 m' pad tail XS,
    ms' = MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (Z_to_bv 64 A) a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F (ret_pc ra) fc None m' (seg_rom asegs)
    /\ munch ((lo, bv_unsigned sp) :: (A + 48, A + elem_block_size name tv) :: XS)%Z m m'
    /\ Forall (fs_scratch H LF) XS
    /\ wmono asegs m m' /\ mem_inv asegs m'
    /\ stk asegs m' lo (bv_unsigned sp)
    /\ rw_cells asegs m' A [CB 48 (firstn 48 junkB)]
    /\ rw_cells asegs m' (A + 48) (ValCells (mkElt f name tv pad tail))
    /\ zlength tail = elem_block_size name tv - 60 - zlength name - zlength tv
    /\ bytes_at asegs m' np name /\ bytes_at asegs m' vp' tv
    /\ as_RHEAP H s LB m' /\ as_RFS H LF m' /\ ACONST m' /\ stack0 m' lo shi.

Definition tc_seg2_stmt : Prop := forall (s : as_St H) (LB : list block) (LF : list fframe) (p : bptr)
    (A f np vp' : Z) (name tv : list byte) (lo shi : Z) (junkF junkB : list byte)
    (ra sp : word) gp tp (t0 t1 t2 s0 s1 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 s3x : word)
    (F : bvmap 5 word) fc (m : mem),
  tc_frame m sp ra s0 s1 s2 s3 s4 s5 junkF ->
  rw_cells asegs m A [CB (Z.to_nat (elem_block_size name tv)) junkB] ->
  bytes_at asegs m np name -> bytes_at asegs m vp' tv ->
  zlength name <= 65533 -> zlength tv <= 65533 -> 0 <= f < 2^16 ->
  (np + zlength name <= A \/ A + elem_block_size name tv <= np) -> (vp' + zlength tv <= A \/ A + elem_block_size name tv <= vp') ->
  (np + zlength name <= lo \/ bv_unsigned sp <= np) -> (vp' + zlength tv <= lo \/ bv_unsigned sp <= vp') ->
  stk asegs m lo (bv_unsigned sp + -80) -> lo + TC_SEG2_STACK <= bv_unsigned sp -> aceil <= lo ->
  mem_inv asegs m ->
  (* [comment removed for export] *)
  bv_unsigned sp mod 16 = 0 -> tp = Z_to_bv 64 ATP -> ACONST m ->
  as_RHEAP H s LB m -> as_RFS H LF m -> (length LF < AFS_MAXLIVE)%nat ->
  stack0 m lo shi -> bv_unsigned sp <= shi ->
  In (p, A, elem_block_size name tv) LB -> addressable m A (elem_block_size name tv) ->
  win_obj LB LF m name np -> win_obj LB LF m tv vp' ->
  evt asegs (tc_seg2_post ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc s LB LF A f np vp' name tv junkB lo shi m)
    (MS (mkR (Z_to_bv 64 P_A_TCNE_RET1) (Z_to_bv 64 (bv_unsigned sp + -80)) gp tp t0 t1 t2
              (Z_to_bv 64 (zlength name)) (Z_to_bv 64 np) (Z_to_bv 64 A) a1 a2 a3 a4 a5 a6 a7
              (Z_to_bv 64 f) s3x (Z_to_bv 64 (zlength tv)) (Z_to_bv 64 vp') s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
        F (Z_to_bv 64 P_A_TCNE_RET1) fc None m (seg_rom asegs)).

